9	/// Managed Python headless-engine CLI arguments.
10	#[derive(Debug, Clone, Args, PartialEq, Eq)]
11	pub struct ManagedEngineArgs {
12	    /// Python executable used to launch the managed headless vLLM engine.
13	    #[arg(long, env = "VLLM_RS_PYTHON", default_value = "python3")]
14	    pub python: String,
15	    /// Host/IP used both for the managed-engine handshake endpoint and the
16	    /// frontend-advertised input/output ZMQ socket addresses.
17	    #[arg(
18	        long = "data-parallel-address",
19	        visible_alias = "handshake-host",
20	        default_value = "127.0.0.1"
21	    )]
22	    pub handshake_host: String,
23	    /// Optional TCP port for the managed-engine handshake / data-parallel RPC
24	    /// endpoint.
25	    ///
26	    /// When omitted, the CLI allocates an ephemeral port automatically.
27	    #[arg(
28	        long = "data-parallel-rpc-port",
29	        visible_alias = "handshake-port",
30	        value_parser = clap::value_parser!(u16).range(1..)
31	    )]
32	    pub handshake_port: Option<u16>,
33	    /// Number of data parallel replicas across the whole deployment.
34	    #[arg(long, default_value_t = 1)]
35	    pub data_parallel_size: usize,
36	    /// Number of data parallel replicas to run on this node.
37	    #[arg(long)]
38	    pub data_parallel_size_local: Option<usize>,
39	
40	    /// Additional arguments forwarded to `python -m vllm.entrypoints.cli.main
41	    /// serve ...`.
42	    ///
43	    /// Arguments after an explicit `--` are forwarded verbatim. Before `--`,
44	    /// `vllm-rs serve` automatically keeps recognized frontend options on
45	    /// the Rust side and forwards everything else to Python.
46	    #[arg(
47	        last = true,
48	        allow_hyphen_values = true,
49	        help_heading = "Passthrough arguments"
50	    )]
51	    pub python_args: Vec<String>,
52	}
