54	impl ManagedEngineArgs {
55	    /// Build the handshake address shared by the Rust frontend and managed
56	    /// Python engine.
57	    pub fn handshake_address(&self, handshake_port: u16) -> String {
58	        format!("tcp://{}:{}", self.handshake_host, handshake_port)
59	    }
