61	    /// Resolve the handshake port, either from the CLI argument (if specified)
62	    /// or by allocating a fresh port.
63	    pub fn resolve_handshake_port(&self) -> anyhow::Result<u16> {
64	        self.handshake_port
65	            .map(Ok)
66	            .unwrap_or_else(|| allocate_handshake_port(&self.handshake_host))
67	    }
