69	    /// Build the managed Python-engine spawn configuration.
70	    pub fn into_config(
71	        self,
72	        model: String,
73	        max_model_len: Option<u32>,
74	        language_model_only: bool,
75	        handshake_port: u16,
76	    ) -> ManagedEngineConfig {
77	        let mut python_args = self.python_args;
78	        // Manually forward some args to the Python engine.
79	        if let Some(max_model_len) = max_model_len {
80	            python_args.push("--max-model-len".to_string());
81	            python_args.push(max_model_len.to_string());
82	        }
83	        if language_model_only {
84	            python_args.push("--language-model-only".to_string());
85	        }
86	        if let Some(data_parallel_size_local) = self.data_parallel_size_local {
87	            python_args.push("--data-parallel-size-local".to_string());
88	            python_args.push(data_parallel_size_local.to_string());
89	        }
90	
91	        ManagedEngineConfig {
92	            python: self.python,
93	            model,
94	            handshake_host: self.handshake_host,
95	            handshake_port,
96	            data_parallel_size: self.data_parallel_size,
97	            python_args,
98	        }
99	    }
