101	    /// Return the number of engines that the Rust frontend should expect to
102	    /// coordinate with.
103	    fn local_engine_count(&self) -> usize {
104	        self.data_parallel_size_local.unwrap_or(self.data_parallel_size)
105	    }
106	
107	    /// Return whether the managed Rust frontend only needs to communicate with
108	    /// colocated engines.
109	    pub fn frontend_local_only(&self) -> bool {
110	        self.data_parallel_size_local != Some(0)
111	            && self.local_engine_count() == self.data_parallel_size
112	    }
113	}
