137	/// Repartition managed-engine argv so Rust-owned flags stay before `--`, while
138	/// everything else is forwarded to Python.
139	pub fn repartition_managed_engine_args<C>(
140	    args: &[OsString],
141	    subcommand: Option<&str>,
142	) -> Result<Vec<OsString>, clap::Error>
143	where
144	    C: CommandFactory,
145	{
146	    let command = C::command();
147	    let (prefix, real_args, command) = match subcommand {
148	        Some(subcommand) => {
149	            if !matches_subcommand(args, subcommand) {
150	                return Ok(args.to_vec());
151	            };
152	
153	            let subcommand = command
154	                .find_subcommand(subcommand)
155	                .expect("managed-engine subcommand should exist");
156	
157	            (args[..2].to_vec(), &args[2..], subcommand)
158	        }
159	        None => {
160	            let Some(program) = args.first() else {
161	                return Ok(args.to_vec());
162	            };
163	
164	            (vec![program.clone()], &args[1..], &command)
165	        }
166	    };
167	
168	    let mut repartitioned = prefix;
169	    repartitioned.extend(repartition_real_managed_engine_args(real_args, command)?);
170	    Ok(repartitioned)
171	}
172	
173	fn repartition_real_managed_engine_args(
174	    args: &[OsString],
175	    command: &clap::Command,
176	) -> Result<Vec<OsString>, clap::Error> {
177	    let Some(model) = args.first() else {
178	        return Ok(args.to_vec());
179	    };
180	
181	    let model = model.to_string_lossy();
182	    if is_help_flag(&model) {
183	        return Ok(args.to_vec());
184	    }
185	    if model == "--" || is_option_like(&model) {
186	        return Err(build_missing_model_error(command));
187	    }
188	
189	    let (long_flags, short_flags) = collect_option_names(command);
190	    let (front_args, explicit_passthrough, had_separator) = split_managed_engine_args(&args[1..]);
191	    let normalized_front_args = normalize_python_arg_aliases(front_args);
192	
193	    let mut frontend_chunks = Vec::new();
194	    let mut python_chunks = Vec::new();
195	    let mut current_chunk = Vec::new();
196	
197	    for arg in normalized_front_args {
198	        let text = arg.to_string_lossy();
199	        if is_option_like(&text) && !current_chunk.is_empty() {
200	            push_chunk(
201	                &mut frontend_chunks,
202	                &mut python_chunks,
203	                std::mem::take(&mut current_chunk),
204	                &long_flags,
205	                &short_flags,
206	            );
